/**
 * Deterministic city → plaka kodu → İBBS Düzey-2 (NUTS-2) lookup.
 * The LLM only ever returns a free-text city name; region codes are resolved here,
 * never generated by the model, because they key the TÜİK multiplier sets.
 */

export type Nuts2Code =
  | "TR10" | "TR21" | "TR22" | "TR31" | "TR32" | "TR33" | "TR41" | "TR42"
  | "TR51" | "TR52" | "TR61" | "TR62" | "TR63" | "TR71" | "TR72" | "TR81"
  | "TR82" | "TR83" | "TR90" | "TRA1" | "TRA2" | "TRB1" | "TRB2" | "TRC1"
  | "TRC2" | "TRC3";

export interface Province {
  code: number; // plaka kodu
  name: string;
  nuts2: Nuts2Code;
}

