/** Folds Turkish casing + diacritics so "izmir", "IZMIR", "İzmir", "Izmir" all match. */
export function foldTr(input: string): string {
  return input
    .trim()
    .replace(/İ/g, "i")
    .replace(/I/g, "ı")
    .toLocaleLowerCase("tr-TR")
    .replace(/ı/g, "i")
    .replace(/ğ/g, "g")
    .replace(/ü/g, "u")
    .replace(/ş/g, "s")
    .replace(/ö/g, "o")
    .replace(/ç/g, "c")
    .replace(/[^a-z0-9]/g, "");
}

const ALIASES: Record<string, number> = {
  icel: 33,
  antep: 27,
  maras: 46,
  urfa: 63,
  afyon: 3,
  smyrna: 35,
  constantinople: 34,
  istanbulasia: 34,
};

const BY_FOLDED = new Map<string, Province>(PROVINCES.map((p) => [foldTr(p.name), p]));

export function resolveProvince(city: string | null | undefined): Province | null {
  if (!city) return null;
  const key = foldTr(city.split(/[,/(]/)[0] ?? city);
  const direct = BY_FOLDED.get(key);
  if (direct) return direct;
  const alias = ALIASES[key];
  return alias ? (PROVINCES[alias - 1] ?? null) : null;
}
